const deal = $json;

const stage = deal.StageName || "";

const emailCount = Number(deal.email_count_14d || 0);
const meetingCount = Number(deal.meeting_count_14d || 0);
const daysSinceLastEmail = Number(deal.days_since_last_email ?? 999);
const daysSinceLastMeeting = Number(deal.days_since_last_meeting ?? 999);

// Email engagement score
let emailScore = 0;
if (emailCount >= 6) emailScore = 25;
else if (emailCount >= 4) emailScore = 18;
else if (emailCount >= 2) emailScore = 10;
else if (emailCount >= 1) emailScore = 5;

// Meeting engagement score
let meetingScore = 0;
if (meetingCount >= 3) meetingScore = 25;
else if (meetingCount >= 2) meetingScore = 18;
else if (meetingCount >= 1) meetingScore = 10;

// Email recency score
let emailRecencyScore = 0;
if (daysSinceLastEmail <= 1) emailRecencyScore = 15;
else if (daysSinceLastEmail <= 3) emailRecencyScore = 10;
else if (daysSinceLastEmail <= 7) emailRecencyScore = 5;

// Meeting recency score
let meetingRecencyScore = 0;
if (daysSinceLastMeeting <= 2) meetingRecencyScore = 15;
else if (daysSinceLastMeeting <= 5) meetingRecencyScore = 10;
else if (daysSinceLastMeeting <= 10) meetingRecencyScore = 5;

// Stage score
let stageScore = 0;
const advancedStages = ["Proposal/Price Quote", "Negotiation/Review"];
const midStages = ["Qualification", "Needs Analysis", "Value Proposition"];

if (advancedStages.includes(stage)) stageScore = 20;
else if (midStages.includes(stage)) stageScore = 12;
else if (stage) stageScore = 6;

// Inactivity penalty
let inactivityPenalty = 0;
const minDays = Math.min(daysSinceLastEmail, daysSinceLastMeeting);

if (minDays >= 14) inactivityPenalty = 15;
else if (minDays >= 10) inactivityPenalty = 10;
else if (minDays >= 7) inactivityPenalty = 5;

// Final score
let momentumScore =
  emailScore +
  meetingScore +
  emailRecencyScore +
  meetingRecencyScore +
  stageScore -
  inactivityPenalty;

momentumScore = Math.max(0, Math.min(100, momentumScore));

let momentumBand = "Low";
if (momentumScore >= 75) momentumBand = "High";
else if (momentumScore >= 45) momentumBand = "Medium";

// Optional trend label
let momentumStatus = "Cold";
if (momentumScore >= 75) momentumStatus = "Hot";
else if (momentumScore >= 45) momentumStatus = "Active";

// Reason drivers
const positives = [];
const negatives = [];

if (emailCount >= 4) positives.push(`strong email activity (${emailCount} emails in 14d)`);
else if (emailCount === 0) negatives.push("no recent email activity");

if (meetingCount >= 2) positives.push(`strong meeting activity (${meetingCount} meetings in 14d)`);
else if (meetingCount === 0) negatives.push("no recent meetings");

if (daysSinceLastEmail <= 3) positives.push(`very recent email activity (${daysSinceLastEmail} day(s) ago)`);
else if (daysSinceLastEmail >= 10) negatives.push(`email activity is stale (${daysSinceLastEmail} days ago)`);

if (daysSinceLastMeeting <= 5) positives.push(`recent meeting activity (${daysSinceLastMeeting} day(s) ago)`);
else if (daysSinceLastMeeting >= 10) negatives.push(`meeting activity is stale (${daysSinceLastMeeting} days ago)`);

if (advancedStages.includes(stage)) positives.push(`deal is in an advanced stage (${stage})`);
else if (!stage) negatives.push("deal stage is missing");

return {
  json: {
    ...deal,
    momentum_score: momentumScore,
    momentum_band: momentumBand,
    momentum_status: momentumStatus,
    score_breakdown: {
      email_score: emailScore,
      meeting_score: meetingScore,
      email_recency_score: emailRecencyScore,
      meeting_recency_score: meetingRecencyScore,
      stage_score: stageScore,
      inactivity_penalty: inactivityPenalty
    },
    positive_drivers: positives,
    negative_drivers: negatives
  }
};

const emailItems = $items("Fetch Deal Emails");
const contactEmail = $item(0).$node["Fetch Contact Details"].json["Email"];
const dealId = $item(0).$node["Fetch Opportunity Details"].json["Id"];

const count = emailItems.length;

let lastEmailAt = null;
let daysSinceLastEmail = 999;

if (count > 0) {
  const dates = emailItems
    .map(item => item.json.internalDate || null)
    .filter(Boolean)
    .map(d => Number(d));

  if (dates.length > 0) {
    const latest = Math.max(...dates);
    lastEmailAt = new Date(latest).toISOString();
    daysSinceLastEmail = Math.floor((Date.now() - latest) / (1000 * 60 * 60 * 24));
  }
}

return [
  {
    json: {
      deal_id: dealId,
      contact_email: contactEmail,
      email_count_14d: count,
      last_email_at: lastEmailAt,
      days_since_last_email: daysSinceLastEmail
    }
  }
];

const meetingItems = $items("Fetch Deal Meetings");
const contactEmail = $item(0).$node["Fetch Contact Details"].json["Email"];
const dealId = $item(0).$node["Fetch Opportunity Details"].json["Id"];

const validMeetings = meetingItems.filter(
  item =>
    item.json &&
    (item.json.start?.dateTime ||
     item.json.start?.date ||
     item.json.created)
);

const count = validMeetings.length;

let lastMeetingAt = null;
let daysSinceLastMeeting = 999;

if (count > 0) {
  const dates = validMeetings
    .map(item =>
      item.json.start?.dateTime ||
      item.json.start?.date ||
      item.json.created ||
      null
    )
    .filter(Boolean)
    .map(d => new Date(d).getTime());

  if (dates.length > 0) {
    const latest = Math.max(...dates);
    lastMeetingAt = new Date(latest).toISOString();
    daysSinceLastMeeting = Math.floor((Date.now() - latest) / (1000 * 60 * 60 * 24));
  }
}

return [
  {
    json: {
      deal_id: dealId,
      contact_email: contactEmail,
      meeting_count_14d: count,
      last_meeting_at: lastMeetingAt,
      days_since_last_meeting: daysSinceLastMeeting
    }
  }
];

const raw = $json.text;

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    momentum_reason: raw,
    next_action: "Unable to parse structured response"
  };
}

return {
  json: {
    ...parsed
  }
};

